import { getProjectPublicDashboardMetadata } from '~/client';

/**
 * Metadata probe for the public (hash-addressed) project dashboard, shared by the per-tab pages
 * under pages/share/project/dashboard/[hash]/. Resolves the project type (canvassing vs legacy)
 * and 404s the whole page on an invalid or disabled hash.
 */
export function usePublicDashboardMetadata(dashboardHash: MaybeRefOrGetter<string>) {
  const {
    data: metadata,
    error,
    isLoading,
  } = useQuery({
    key: () => ['public.dashboard.metadata', toValue(dashboardHash)],
    query: () =>
      getProjectPublicDashboardMetadata({
        composable: '$fetch',
        path: { public_hash: toValue(dashboardHash) },
      }),
    enabled: () => !!toValue(dashboardHash),
  });

  const isCanvassing = computed(() => metadata.value?.type === 'canvassing');

  // An invalid or disabled dashboard hash 404s from the metadata probe — surface
  // it as a real 404 page rather than an inline error.
  watch(
    () => error.value,
    (newError) => {
      if (newError && newError.statusCode === 404) {
        throw createError({
          statusCode: 404,
          statusMessage: 'Failed to load dashboard',
          fatal: true,
        });
      }
    }
  );

  return { metadata, error, isLoading, isCanvassing };
}
